(()=>{
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let cleanup=()=>{},controller=null;
function stop(){cleanup();cleanup=()=>{};controller?.abort();controller=null;window.speechSynthesis?.cancel()}
function lesson(){return window.BoraCourses[0].lessons.find(l=>l.id===location.hash.split('/')[1])}
function page(u){const l=lesson();if(!l)return '<div class="panel"><h1>Выбери урок для разговора</h1><a href="#courses/pt">Программа курса</a></div>';return `<div class="narrow"><a class="back" href="#courses/pt/${esc(l.id)}">← К уроку</a><div class="eyebrow">Голосовая практика · Português do Brasil</div><h1>Поговорим: ${esc(l.title)}</h1><p>${esc(l.scene)}</p><div class="notice">Bora знает тему урока. Говори коротко, спрашивай «почему» по-русски, проси объяснить проще. Один ответ — одна полезная поправка.</div><div class="panel practice-panel"><label>Бразильский голос<select id="practice-voice" aria-label="Бразильский голос"></select></label><p id="voice-availability" class="small"></p><audio id="practice-player" controls preload="none" aria-label="Ответ Bora голосом"></audio><label><input type="checkbox" id="practice-autoplay" checked> Озвучивать ответы на португальском</label><label>Скорость<select id="practice-speed"><option value="1">Обычно</option><option value="0.85">Медленнее</option></select></label><div id="practice-messages" aria-live="polite"></div><button class="btn" id="practice-start">Начать разговор →</button><form id="practice-form"><label>Язык твоего ответа<select id="recognition-language"><option value="pt-BR">Португальский (Бразилия)</option><option value="ru-RU">Русский — вопрос к объяснению</option></select></label><button type="button" class="btn alt" id="practice-mic">🎙 Говорить</button><button type="button" class="btn alt" id="practice-mic-stop" disabled>Остановить микрофон</button><label>Твой ответ или вопрос<textarea id="practice-input" maxlength="1500" placeholder="Скажи или напиши ответ. Перед отправкой проверь распознанный текст." required></textarea></label><button class="btn" id="practice-send">Отправить →</button></form><p id="practice-status" role="status" aria-live="polite"></p><p id="speech-status" role="status"></p><p class="small">Распознавание браузера может передавать звук своему поставщику. В ГигаЧат отправляются текст ответа, тема и несколько последних реплик. В аккаунте сохраняется текст, не аудиозапись. По тексту нельзя надёжно оценить акцент или произношение.</p><p class="small">Озвучка — синтетический бразильский голос Francisca, а не запись носителя. Португальская реплика передаётся речевому сервису Microsoft. Если микрофон недоступен, попробуй актуальный Chrome или Edge либо напиши ответ.</p><button class="btn alt" id="practice-finish">Завершить практику</button><p id="practice-summary" class="small"></p></div></div>`}
function bind(u,save){const l=lesson(),$=s=>document.querySelector(s);if(!l||!$('#practice-form'))return;
u.voicePractice??={};const r=u.voicePractice[l.id]??={messages:[],turns:0,draft:'',startedAt:new Date().toISOString()};const input=$('#practice-input'),messages=$('#practice-messages'),status=$('#practice-status'),speechStatus=$('#speech-status'),voice=$('#practice-voice'),availability=$('#voice-availability');let alive=true,busy=false,recognition=null,timer=null,voices=[],audioAbort=null;const player=$("#practice-player"),audioCache=new Map();const stopVoice=()=>{audioAbort?.abort();player.pause();window.speechSynthesis?.cancel()};
input.value=r.draft||'';const paint=()=>{messages.innerHTML=r.messages.map((m,i)=>`<article class="card" style="margin:16px 0"><strong>${m.role==='user'?'Ты':'Bora'}</strong><p lang="${m.role==='assistant'?'pt-BR':'und'}">${esc(m.say||m.content)}</p>${m.role==='assistant'?`<p class="small">${esc(m.translation)}</p><p>${esc(m.feedback)}</p>${(m.sources||[]).filter(s=>String(s.url).startsWith("https://")).map(s=>`<p class="small"><a href="${esc(s.url)}" target="_blank" rel="noopener">[${esc(s.number)}] ${esc(s.title)} · ${esc(s.license)}</a></p>`).join("")}<button type="button" class="btn alt" data-practice-speak="${i}">▶ Послушать</button>`:''}</article>`).join('');$('#practice-start').hidden=!!r.messages.length;$('#practice-summary').textContent=`Твоих ответов: ${r.turns}. ${r.finishedAt?'Практика отмечена как завершённая.':'После трёх ответов можно подвести итог.'}`;document.querySelectorAll('[data-practice-speak]').forEach(b=>b.onclick=()=>speak(r.messages[Number(b.dataset.practiceSpeak)].say));};
const populate=()=>{const previous=voice.value||'server';voices=(window.speechSynthesis?.getVoices()||[]).filter(v=>v.lang.replace('_','-').toLowerCase()==='pt-br');voices.sort((a,b)=>Number(/Francisca|Natural|Neural/i.test(b.name))-Number(/Francisca|Natural|Neural/i.test(a.name)));voice.innerHTML='<option value="server">Francisca · Бразилия · нейроголос</option>'+voices.map((v,i)=>`<option value="${i}">${esc(v.name)} · pt-BR</option>`).join('');if(previous==='server'||voices[Number(previous)])voice.value=previous;availability.textContent='По умолчанию — бразильский нейроголос Francisca с сервера. Доступные голоса pt-BR твоего устройства можно выбрать дополнительно.'};
async function speak(text){stopVoice();if(voice.value==='server'){speechStatus.textContent='Готовлю бразильскую озвучку…';const request=new AbortController();audioAbort=request;try{let url=audioCache.get(text);if(!url){const response=await fetch('/api/speech',{method:'POST',headers:{'Content-Type':'application/json',Authorization:'Bearer '+await window.BoraAccount.accessToken()},body:JSON.stringify({text}),signal:AbortSignal.any([request.signal,AbortSignal.timeout(65000)])});if(!response.ok){const error=await response.json();throw Error(error.error||'Озвучка недоступна')}url=URL.createObjectURL(await response.blob());if(!alive){URL.revokeObjectURL(url);return}audioCache.set(text,url);if(audioCache.size>12){const key=audioCache.keys().next().value;URL.revokeObjectURL(audioCache.get(key));audioCache.delete(key)}}if(!alive||request.signal.aborted)return;player.src=url;player.playbackRate=Number($('#practice-speed').value);await player.play();speechStatus.textContent='Слушаем. Когда будешь готов — нажми «Говорить».'}catch(e){if(alive&&e.name!=='AbortError')speechStatus.textContent=e.message||'Нажми ▶ в плеере, чтобы послушать.'}return}const chosen=voices[Number(voice.value)];if(!chosen||!window.SpeechSynthesisUtterance){speechStatus.textContent='Бразильский голос недоступен. Русским или европейским голосом фразу не заменяем.';return}const utterance=new window.SpeechSynthesisUtterance(text);utterance.lang='pt-BR';utterance.voice=chosen;utterance.rate=Number($('#practice-speed').value);utterance.onstart=()=>{if(alive)speechStatus.textContent='Слушаем ответ…'};utterance.onend=()=>{if(alive)speechStatus.textContent='Теперь твоя очередь.'};utterance.onerror=()=>{if(alive)speechStatus.textContent='Озвучка не запустилась. Нажми «Послушать» ещё раз.'};window.speechSynthesis.speak(utterance)}
const Recognition=window.SpeechRecognition||window.webkitSpeechRecognition;
if(!Recognition){$('#practice-mic').disabled=true;speechStatus.textContent='В этом браузере распознавание недоступно. Открой сайт в Chrome/Edge или введи ответ текстом.'}
const endMic=()=>{clearTimeout(timer);if(recognition){recognition.abort();recognition=null}if(alive){$('#practice-mic').disabled=!Recognition;$('#practice-mic-stop').disabled=true}};
$('#practice-mic').onclick=()=>{if(busy)return;stopVoice();endMic();recognition=new Recognition();recognition.lang=$('#recognition-language').value;recognition.continuous=false;recognition.interimResults=false;recognition.maxAlternatives=1;recognition.onresult=e=>{if(!alive)return;const text=e.results[0]?.[0]?.transcript||'';input.value=(input.value+' '+text).trim().slice(0,1500);r.draft=input.value;save();speechStatus.textContent='Проверь распознанный текст и нажми «Отправить».'};recognition.onerror=e=>{if(alive)speechStatus.textContent=e.error==='not-allowed'?'Разреши доступ к микрофону в настройках сайта. Можно написать ответ.':'Не удалось распознать речь. Попробуй снова или напиши ответ.'};recognition.onend=()=>{clearTimeout(timer);if(alive){$('#practice-mic').disabled=false;$('#practice-mic-stop').disabled=true}};try{recognition.start();$('#practice-mic').disabled=true;$('#practice-mic-stop').disabled=false;speechStatus.textContent='Слушаю. Говори короткой фразой…';timer=setTimeout(()=>recognition?.stop(),30000)}catch{speechStatus.textContent='Микрофон не запустился. Попробуй ещё раз или введи текст.';endMic()}};
$('#practice-mic-stop').onclick=()=>recognition?.stop();input.oninput=()=>{r.draft=input.value;save()};
async function send(start=false){if(busy)return;const question=start?'Начни короткий разговор по ситуации урока.':input.value.trim();if(!question)return;endMic();stopVoice();busy=true;$('#practice-send').disabled=true;$('#practice-start').disabled=true;$('#practice-mic').disabled=true;status.textContent='Bora готовит короткую реплику…';const requestController=new AbortController();controller=requestController;const deadline=setTimeout(()=>requestController.abort(),120000);
try{const response=await fetch('/api/chat',{method:'POST',headers:{'Content-Type':'application/json',Authorization:'Bearer '+await window.BoraAccount.accessToken()},body:JSON.stringify({question,language:'pt-BR',mode:'practice',lessonId:l.id,learner:{goal:u.goal,experience:u.experience,diagnosis:u.diagnosis?.summary||''},history:r.messages.slice(-6).map(m=>({role:m.role,content:m.content}))}),signal:requestController.signal});const value=await response.json();if(!response.ok)throw Error(value.error||'Не удалось получить ответ');if(!value.practice)throw Error('Не удалось разобрать реплику. Попробуй ещё раз.');if(!alive)return;if(!start){r.messages.push({role:'user',content:question});r.turns++}r.messages.push({role:'assistant',content:value.answer,sources:value.sources,...value.practice});r.messages=r.messages.slice(-12);r.draft='';input.value='';save();paint();status.textContent='Можно ответить голосом или задать вопрос по-русски.';if($('#practice-autoplay').checked)speak(value.practice.say)}catch(e){if(alive)status.textContent=e.name==='AbortError'?'Ответ занял слишком много времени. Твоя фраза сохранена — попробуй ещё раз.':e.message}finally{clearTimeout(deadline);if(controller===requestController)controller=null;if(alive){busy=false;$('#practice-send').disabled=false;$('#practice-start').disabled=false;$('#practice-mic').disabled=!Recognition}}}
$('#practice-start').onclick=()=>send(true);$('#practice-form').onsubmit=e=>{e.preventDefault();send()};$('#practice-finish').onclick=()=>{if(r.turns<3){status.textContent='Попробуй ответить хотя бы три раза. Можно задавать простые вопросы.';return}r.finishedAt=new Date().toISOString();save();paint();status.textContent='Практика сохранена. Можно продолжать разговор или вернуться к уроку.'};populate();window.speechSynthesis?.addEventListener('voiceschanged',populate);paint();$('#practice-speed').onchange=()=>{player.playbackRate=Number($('#practice-speed').value)};cleanup=()=>{alive=false;endMic();stopVoice();player.removeAttribute('src');player.load();for(const url of audioCache.values())URL.revokeObjectURL(url);window.speechSynthesis?.removeEventListener('voiceschanged',populate)};
}
window.BoraPractice={page,bind,stop};
})();
